head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > setDisabled]<br/>컴포넌트의 비활성화(disabled) 상태를 설정합니다.",
    "validation" : [
        "disabled(필수) 파라미터로 비활성화(disabled) 상태를 true/false 로 설정합니다. ",
        "비활성화(disabled) 상태이면 컴포넌트에 대한 입력, 포커스, 이벤트 등이 차단됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onfocus", "onmousedown", "onkeydown", "onchange", "onclick"])

    $c.gcm.createBasicInputCalendar('', eList); 
}



scwin.btn_getClass_onclick = function (e) {
    // id가 "target1"을 포함하는 요소를 찾기
    let targetEmement = document.querySelector('[id*="target1"]');

    if (targetEmement) {
        let inputElement = null;
        let buttonElement = null;
        let imageElement = null;

        if (target1.options.renderDiv === true) {
            // id가 "target1_input"을 포함하는 input 태그 찾기
            inputElement = targetEmement.querySelector('input[id*="target1_input"]');

            // id가 "target1_img"인 button 태그 찾기
            buttonElement = targetEmement.querySelector('button[id*="target1_img"]');

            wf_body_bottom.getObj("scwin").setReturnValue('input class :' + inputElement.className);
            wf_body_bottom.getObj("scwin").setReturnValue('button class :' + buttonElement.className);
        }
        else {
            // id가 "target1_input"을 포함하는 input 태그 찾기
            inputElement = targetEmement.querySelector('input[id*="target1_input"]');

            // id가 "target1_img"인 image 태그 찾기
            imageElement = targetEmement.querySelector('img[id*="target1_img"]');    

            wf_body_bottom.getObj("scwin").setReturnValue('input class :' + inputElement.className);
            wf_body_bottom.getObj("scwin").setReturnValue('image class :' +imageElement.className);        
        }
    }
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus=====");    
}


scwin.target1_onmousedown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmousedown=====");    
}


scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeydown=====");        
}


scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");        
}


scwin.target1_onclick = function (e) {
    setTimeout(() => {
        let popupCalendar = document.querySelector('[id*="target1_calendar"]');  

        if (popupCalendar) {
            if (popupCalendar.style.display == "block")
                wf_body_bottom.getObj("scwin").setReturnValue("show popupCalendar");
        }
    }, 100);
}



scwin.btn_setDisabled_onclick = function (e) {
	target1.setDisabled(par_disabled.getText());
};
